const operations = $input.all();

// Calculate statistics
const totalOps = operations.length;
const profitable = operations.filter(op => op.json.profit > 0).length;
const losses = operations.filter(op => op.json.profit < 0).length;
const avgProfit = operations.reduce((sum, op) => sum + (op.json.profit || 0), 0) / totalOps;

// Identify patterns
const byStrategy = {};
operations.forEach(op => {
  const strategy = op.json.strategy || 'unknown';
  if (!byStrategy[strategy]) {
    byStrategy[strategy] = { count: 0, totalProfit: 0, wins: 0, losses: 0 };
  }
  byStrategy[strategy].count++;
  byStrategy[strategy].totalProfit += op.json.profit || 0;
  if (op.json.profit > 0) byStrategy[strategy].wins++;
  else if (op.json.profit < 0) byStrategy[strategy].losses++;
});

return [{
  json: {
    totalOperations: totalOps,
    profitableOps: profitable,
    lossOps: losses,
    winRate: (profitable / totalOps * 100).toFixed(2),
    avgProfit: avgProfit.toFixed(2),
    strategyPerformance: byStrategy,
    rawOperations: operations.map(op => op.json)
  }
}];

