{
  "type": "object",
  "properties": {
    "needsImprovement": {
      "type": "boolean",
      "description": "Whether the bot needs adjustments based on analysis"
    },
    "summary": {
      "type": "string",
      "description": "Brief summary of findings"
    },
    "recommendations": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "priority": {
            "type": "string",
            "enum": ["high", "medium", "low"]
          },
          "category": {
            "type": "string",
            "description": "Category like risk_management, entry_logic, exit_strategy, position_sizing"
          },
          "issue": {
            "type": "string",
            "description": "What problem was identified"
          },
          "recommendation": {
            "type": "string",
            "description": "Specific change to implement"
          },
          "codeSnippet": {
            "type": "string",
            "description": "Python code example if applicable"
          }
        }
      }
    }
  },
  "required": ["needsImprovement", "summary", "recommendations"]
}

