const analysis = $input.first().json;

if (!analysis.needsImprovement) {
  return [{
    json: {
      action: 'no_update_needed',
      message: 'Bot performance is acceptable, no changes required',
      summary: analysis.summary
    }
  }];
}

// Generate improvement report
const improvements = {
  action: 'update_required',
  timestamp: new Date().toISOString(),
  summary: analysis.summary,
  highPriorityChanges: analysis.recommendations.filter(r => r.priority === 'high'),
  mediumPriorityChanges: analysis.recommendations.filter(r => r.priority === 'medium'),
  lowPriorityChanges: analysis.recommendations.filter(r => r.priority === 'low'),
  allRecommendations: analysis.recommendations
};

return [{ json: improvements }];

const improvements = $input.first().json;
const botCode = $input.first().binary.data.toString('utf-8');

if (improvements.action === 'no_update_needed') {
  return [{
    json: {
      updated: false,
      message: 'No improvements needed',
      originalCode: botCode
    }
  }];
}

// Create improvement instructions for AI
const improvementInstructions = improvements.allRecommendations
  .filter(r => r.priority === 'high' || r.priority === 'medium')
  .map(r => `${r.category}: ${r.recommendation}${r.codeSnippet ? '\n' + r.codeSnippet : ''}`)
  .join('\n\n');

return [{
  json: {
    updated: true,
    originalCode: botCode,
    improvementInstructions: improvementInstructions,
    recommendations: improvements.allRecommendations,
    summary: improvements.summary
  }
}];

